select id, starts_on, ends_on, max(discount_pct) over (partition by channel) channel_max_discount_pct, lead(discount_pct, 1) over (partition by promo_code order by ends_on asc, id asc) next_discount_pct, sum(discount_pct) over (partition by promo_code order by starts_on asc, id asc rows between unbounded preceding and current row) cumulative_discount_pct from promotions where ends_on between '2024-02-01' and '2024-04-26';
